#!/usr/bin/env python3
"""Build human-readable results from local metrics and receipts."""
import json,statistics,collections
from pathlib import Path
P=Path(__file__).resolve().parent
files={}
for cohort in ('','historical-'):
 for form in ('narrative','scoping'):
  stem=cohort+form
  rows=json.loads((P/(stem+'-candidates.json')).read_text()); metrics=json.loads((P/(stem+'-metrics.json')).read_text()); agg=json.loads((P/(stem+'-aggregate.json')).read_text()); files[stem]=(rows,metrics,agg)
def number(v): return f'{v:,.1f}'.removesuffix('.0')
def q(v): return f"{number(v['median'])} ({number(v['p25'])}–{number(v['p75'])})"
lines=['# Narrative and scoping review corpus: bounded pilot','', '## Selection and authority','', 'The exploratory sample searches Europe PMC open-access records for the exact title phrases “narrative review” and “scoping review”, sorted by the service’s `CITED desc` ordering. The selected cases are the first 200 parseable full texts passing publisher-type exclusions among the first 275 title-screen survivors. The historical sample repeats this process with the service filter `FIRST_PDATE:[1900-01-01 TO 2019-12-31]`. The source may assign a different publication year to the same article; each record keeps its reported publication year. These are two overlapping samples, not independent replicates. Searches, results, times, service echo and citation counts are recorded in the JSON receipts and screen files. This is a bounded query ranking, not a global ranking.','', 'A narrative/critical literature review synthesizes a body of literature; it is not a review of one work. Title screening excludes named protocols, systematic and scoping reviews, methods/guidance and other conflicting forms where the rule matches. A publisher `systematic-review` article type also excludes a narrative candidate. Scoping reviews use the NLM form and PRISMA-ScR as anchors; the 2018 guideline is not a date cutoff. Both searches deliberately require a self-described title, so neither represents all work in the form. Publisher article-type and subject labels are retained verbatim; original NLM publication types are retained where supplied. Form classification is provisional: the title and publisher labels do not prove the methods, writing quality, audience, or suitability as a model. No full-set manual semantic or quality assessment has been completed.','', '## Counts and era','','| Sample | Measured | Publication year <2015 | 2015–2019 | 2020+ | Publication years |','| --- | ---: | ---: | ---: | ---: | --- |']
for key,(rows,m,a) in files.items():
 selected=[x for x in rows if x['measured']]; years=[int(x['year']) for x in selected if str(x['year']).isdigit()]; era=[sum(y<2015 for y in years),sum(2015<=y<=2019 for y in years),sum(y>=2020 for y in years)]
 lines.append(f'| {key} | {len(m)} | {era[0]} | {era[1]} | {era[2]} | {min(years)}–{max(years)} |')
for form in ('narrative','scoping'):
 a={x['pmcid'] for x in files[form][0] if x['measured']};b={x['pmcid'] for x in files['historical-'+form][0] if x['measured']}
 lines.append(f'\n{form.capitalize()} samples overlap by {len(a&b)} PMCID records; the union contains {len(a|b)} distinct measured records.')
lines += ['','## Descriptive measures','','Median (interquartile range); document-level quantities weight each article equally. Paragraph and sentence values summarize each article’s median, giving each article equal weight. These observations describe these samples, not targets or limits.','', '| Sample | Body words | Top-level sections | Paragraph words, per-document medians | Sentence words, per-document medians | References | Figures | Tables |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for key,(_,m,a) in files.items(): lines.append('| '+key+' | '+' | '.join(q(a[k]) for k in ('body_words','top_level_sections','paragraph_words_document_medians','sentence_words_document_medians','reference_entries','figures','tables'))+' |')
lines += ['','## Counting and caveats','','- Body prose comprises text of JATS `<p>` elements under `<body>` after removing figure/table wrappers, supplementary material, reference lists, displayed formulae, boxed text, code, preformatted text, lists, and sections whose titles exactly match a controlled list of administrative headings (acknowledgments, contributions, funding, data availability, declarations, ethics, competing interests, footnotes, associated data). Other administrative headings may remain, and a similarly named substantive section can be removed. Section headings, abstracts, captions and references are excluded. Inline markup, including citation labels, remains part of paragraph text. List and code counts are separate XML-element signals, not estimates of their word proportions.','- A word is a Unicode alphanumeric token with optional internal apostrophe or hyphen. Characters count the full token, including its internal punctuation. Sentence segments use a simple punctuation-plus-whitespace-plus-capital/digit heuristic; abbreviations and non-English conventions can produce errors. Paragraph, sentence and word arrays are derived counts, not source prose.','- Section counts and section shares use top-level JATS `<sec>` elements; nested section words are included in their parent. Body paragraphs outside such sections are in the body total but not a section share. Heading-role matches are simple keyword labels, not annotations of communicative function. Maximum heading depth follows nested `<sec>` elements.','- Abstract words count text within JATS `<abstract>`, including any included labels/headings. Reference counts sum direct `<ref>` children of every `<ref-list>` in the article, including lists placed within body sections. Figures, tables, lists, code and bibliographic cross-references are counts of corresponding JATS elements inside the original body; absent or unusual encoding can undercount. Figure/table captions are not body prose. Zero can mean absent markup as well as absence of the item.','- Publication type and title checks are discovery filters, not proof of a representative or high-quality review. Selection is restricted to indexed, open-access English-title matches and citation ordering, biased toward older papers with time to accumulate citations as well as recent highly cited subjects. This corpus is biomedical and is not representative of literature reviews across disciplines. Examples, quotations, audience, paragraph functions and evidence quality have not been assessed. Some section labels are signals rather than function judgments.','', '## Artifacts and reproducibility','', '`*-search-screen.json` records up to the first 1,000 returned records and title rejection matches; `*-candidates.json` records the bounded 275 attempted XML candidates, source identifiers, Europe PMC pubYear, citation count and search snapshot, XML SHA-256 and cache file modification time, article-type labels, and selection outcome. The cache modification time is filesystem evidence, not a verified provider retrieval timestamp. `*-metrics.json` holds per-document derived measurements and section-role signals; `*-aggregate.json` holds descriptive distributions. `receipt.json` and `historical-receipt.json` preserve query and service details. Run `acquire.py` and `acquire-historical.py` with Python 3 and `requests`; cached full-text XML is outside the repository at `/workspace/repos/builderbob/.writing-corpus-cache/narrative-scoping`. `recalculate.py` reproduces the documented corrections to both samples without refetching. Query results and citation counts may drift on rerun.','', 'Definitions: [NLM publication types](https://www.nlm.nih.gov/mesh/pubtypes.html), [PRISMA-ScR](https://www.prisma-statement.org/scoping), [project authority crosswalk](../../../docs/writing-harness/research/authority-and-definition-crosswalk.md).','']
(P/'summary.md').write_text('\n'.join(lines))
